from _lib import File
F=File('pre2020_ktm350','o-k35','KTM 350 SX-F 2011-2019 by generation (2011-2012, 2013-2015, 2016-2018, 2019): what changed, dyno and weight, tester settings, maps, known problems and fixes (knowledge push 2026-11)','KTM',['350 SX-F'],list(range(2011,2020)))
R=F.R; M='magazine'; C=['350 SX-F']

s=F.src(M,"Motocross Action - 2011 KTM 350SXF test","https://motocrossactionmag.com/ten-years-ago-today-complete-test-of-the-2011-ktm-350sxf","2010")
G=[2011,2012]
R('identity','2011 introduction',C,G,"The 350 SX-F was new for 2011: a fuel-injected, electric-start 350 in the steel linkage frame that replaced PDS that year (5 mm lower and 15 mm wider at the pegs), with a steel clutch basket, a 1.98 gal tank and an optional kickstarter. List price $8,499.",{'msrp_usd':8499,'tank_gal':1.98},'OEM',s)
R('power_feel','2011-2012 dyno and weight',C,G,"On a magazine dyno the 2011 350 SX-F made 46.94 hp at 12,200 rpm; the leaner, more advanced 2012 map raised the peak to 48.69 hp at 12,200 rpm and moved power into the middle (46.94 hp at 9,000 rpm). It weighed 236-237 lb without fuel. It has 450-like torque low down but makes its real power above 10,000 rpm.",{'peak_hp_2011':46.94,'peak_hp_2012':48.69,'peak_rpm':12200,'weight_lb':'236-237'},'MEASURED',s,'high')
R('setups','2011 tester settings',C,[2011],"A magazine test crew's 2011 350 SX-F setup: fork 0.50 kg/mm springs (the stock 0.48 are too soft), 365 cc oil (stock 375), compression 12 clicks out, rebound 12 out, legs 5 mm up. Shock 5.7 kg/mm spring (stock 5.4), 100 mm sag, high-speed compression 2-1/4 turns out, low-speed 15 clicks out, rebound 12 out.",{'fork':'0.50 kg/mm (stock 0.48), 365 cc, comp 12 out, reb 12 out, 5 mm up','shock':'5.7 kg/mm (stock 5.4), sag 100 mm, HSC 2-1/4 turns, LSC 15 out, reb 12 out'},'TUNER',s)
R('setups','350 SX-F gearing 2011-2018',C,list(range(2011,2019)),"The 350 SX-F comes with a 50-tooth rear sprocket and testers geared it down every year: 51 is the usual choice, 52 for riders who want to rev it less between shifts. Second to third is a wide gap.",{'stock_rear':50,'tested_rear':'51 (some 52)'},'TUNER',s)
R('ecu_electronics','2011-2015 ignition maps',C,[2011,2012,2013,2014,2015],"The 2011-2015 350 SX-F has three ignition curves stored in the ECU (soft, standard, aggressive) but needs KTM's accessory switch (about $50) to select them. They change timing only, not fuel. Testers ran the aggressive curve.",{'maps':'soft / standard / aggressive, via accessory switch'},'TUNER',s)
s2=F.src(M,"Motocross Action - 2012 KTM 350SXF test","https://motocrossactionmag.com/mxas-2012-ktm-350sxf-motocross-test-has-the-350-experiment-been-a-success-find-out-here","2011")
R('identity','2012 changes',C,[2012],"2012 350 SX-F changes: fuel map leaned 2-3% and ignition advanced about 2 degrees, a redesigned air boot, a better-sealed wiring harness with a boot on the throttle position sensor, the rear master-cylinder port relocated, a 5.7 kg/mm shock spring (was 5.4) with softer low-speed and firmer high-speed damping, more low-speed fork compression, extra fuel-line filters and Dunlop MX51 tyres.",{'shock_spring':'5.7 kg/mm'},'OEM',s2)
R('setups','2012-2013 tester settings',C,[2012,2013],"A magazine test crew's 2012-2013 350 SX-F setup: fork stock 0.48 kg/mm springs, 375 cc oil in 2012 and 390 cc in 2013 (lower it 10 cc for riders under 175 lb), compression 15 clicks out, rebound 15 out, legs 5 mm up. Shock 5.7 kg/mm spring (5.4 for lighter riders), 105 mm sag, high-speed compression 2 turns out, low-speed 15 clicks out, rebound 15 out.",{'fork':'0.48 kg/mm, comp 15 out, reb 15 out, 5 mm up','shock':'5.7 kg/mm, sag 105 mm, HSC 2 turns, LSC 15 out, reb 15 out'},'TUNER',s2)
R('known_issues','2011-2012 weak points and fixes',C,G,"Tester findings on the 2011-2012 350 SX-F: the radiator overflow vents onto the head pipe (longer hose routed under the engine), a boot can catch and unscrew the right-side oil filler cap (clip its wings or fit an aluminium cap), the 2011 throttle position sensor and harness were vulnerable to water (improved for 2012), the water-pump cover seal can leak, the nylon shock preload ring deforms, the 2011 rims were soft, and the backfire screen could pull out of the 2011 air boot.",{},'TUNER',s2)

s=F.src(M,"Motocross Action - 2013 KTM 350SXF test","https://motocrossactionmag.com/ten-years-ago-today-complete-test-of-the-2013-ktm-350sxf","2012")
G=[2013,2014,2015]
R('identity','2013 redesign',C,G,"2013 350 SX-F changes: die-cast cases 1 lb lighter, a new piston on a plain-bearing rod, a reworked head with stiffer valve springs, a 44 mm throttle body (was 42), a frame with a reinforced head tube, a stronger swingarm with a 25 mm rear axle (was 20), lighter clamps, a larger airbox, new bodywork and bars 12 mm taller. The exhaust comes off without removing the shock on this model. This platform ran 2013-2015.",{'throttle_body_mm':44,'rear_axle_mm':25},'OEM',s)
R('power_feel','2013-2015 dyno and weight',C,G,"On a magazine dyno the 2013 350 SX-F made 54.18 hp at 10,800 rpm (2012: about 48), and the unchanged engine was quoted at 54.18 hp at 12,600 rpm in 2015. It weighed 236 lb. It has to be revved: it trails the 450 SX-F until about 11,000 rpm, is strongest from 11,000 to 13,400 rpm and is soft in the middle.",{'peak_hp':54.18,'weight_lb':236,'best_rpm':'11,000-13,400'},'MEASURED',s,'high','The same magazine printed the peak at 10,800 rpm in 2013 and 12,600 rpm in 2015 for the same power figure.')
s2=F.src(M,"Motocross Action - 2014 KTM 350SXF test","https://motocrossactionmag.com/mxas-2014-ktm-350sxf-motocross-test-the-little-bike-that-could-in-the-right-hands","2013")
R('identity','2014 changes',C,[2014],"2014 350 SX-F changes: a 9 mm front master-cylinder piston (was 10) with a new lever, the shared SX-F muffler without internal cones, fork revalved with more low and mid compression, and detail fixes: a water-pump cover with a deeper groove and thicker O-ring, new seat foam, a lighter chain guide, a reworked gas cap and an upgraded harness.",{},'OEM',s2)
R('setups','2014 tester settings',C,[2014],"A magazine test crew's 2014 350 SX-F setup: fork 0.48 kg/mm springs, 380 cc oil (stock 390), compression 15 clicks out, rebound 18 out, legs 5 mm up. Shock 5.7 kg/mm spring (5.4 under 150 lb), 100 mm sag (stock 105), high-speed compression 1-1/2 turns out (stock 2), low-speed 12 clicks out, rebound 15 out.",{'fork':'380 cc (stock 390), comp 15 out, reb 18 out, 5 mm up','shock':'5.7 kg/mm, sag 100 mm, HSC 1-1/2 turns (stock 2), LSC 12 out, reb 15 out'},'TUNER',s2)
s3=F.src(M,"Motocross Action - 2015 KTM 350SXF test","https://motocrossactionmag.com/2015-test-ride-ktm-350sxf","2014")
R('identity','2015 changes',C,[2015],"2015 350 SX-F changes match the 450: WP 4CS fork, a 20 mm front axle with its offset moved 2 mm rearward, a new bell crank with a pull rod 2.5 mm longer, a shock 4 mm longer, a forged cross tube, an orange frame, black Excel rims and Dunlop MX52 tyres. Engine unchanged apart from clutch springs and a seal.",{'fork':'WP 4CS'},'OEM',s3)
R('setups','2015 tester settings (4CS)',C,[2015],"A magazine test crew's 2015 350 SX-F setup: fork 4.8 N/mm springs, compression 20 clicks out (stock 15), rebound 14 out (stock 15), legs 5 mm up, oil lowered in small steps for comfort. Shock 5.7 kg/mm spring, 100 mm sag, high-speed compression 2 turns out, low-speed 15 clicks out, rebound 15 out. Check that the air-filter cage seats properly at the back edge.",{'fork':'comp 20 out (stock 15), reb 14 out, 5 mm up','shock':'5.7 kg/mm, sag 100 mm, HSC 2 turns, LSC 15 out, reb 15 out'},'TUNER',s3)

s=F.src(M,"Motocross Action - 2016 KTM 350SXF race test","https://motocrossactionmag.com/2016-mxa-race-test-ktm-350sxf","2015")
G=[2016,2017,2018]
R('identity','2016 redesign',C,G,"The 2016 350 SX-F shares no engine parts with the 2015 but keeps the 88 x 57.3 mm bore and stroke: cases 20 mm shorter, crank 6 mm higher, lighter cams, seven clutch plates instead of eight and a lithium battery. The frame is 13 oz lighter and 20% stiffer in torsion, with a wheelbase 10 mm shorter and a head angle 0.4 degree steeper; the seat is 10-20 mm lower; the shock spring went from 57 to 48 N/mm. This platform ran 2016-2018.",{'bore_stroke_mm':'88 x 57.3','shock_spring':'48 N/mm'},'OEM',s)
R('power_feel','2016-2018 dyno and weight',C,G,"On a magazine dyno the 2016 350 SX-F made 54.41 hp at 13,200 rpm (37 hp at 7,000, 49.47 at 9,000, 53.49 at 11,000) and weighed 226 lb. The 2017 and 2018 made the same peak and, with the air fork, weighed 221 lb. Smooth and progressive; it rewards revving, and an upshift at 9,000 rpm gives away about 5 hp. Rev limit 13,400 rpm.",{'peak_hp':54.41,'peak_rpm':13200,'weight_lb_2016':226,'weight_lb_2017_18':221,'rev_limit_rpm':13400},'MEASURED',s,'high')
R('setups','2016 tester settings (4CS)',C,[2016],"A magazine test crew's 2016 350 SX-F setup: fork 4.8 N/mm springs, compression 8 clicks out (stock 15), rebound 15 out, legs 5 mm up, 10 cc more oil to firm the second half of the stroke. Shock 48 N/mm spring (45 for riders under 180 lb), 105 mm sag (KTM says 110), high-speed compression 1-3/4 turns out (stock 2), low-speed 15 clicks out, rebound 10 out (stock 15). The thin stock inner tubes puncture easily; fit heavier ones.",{'fork':'comp 8 out (stock 15), reb 15 out, 5 mm up','shock':'48 N/mm (45 under 180 lb), sag 105 mm, HSC 1-3/4 turns, LSC 15 out, reb 10 out'},'TUNER',s)
s2=F.src(M,"Motocross Action - 2017 KTM 350SXF race test","https://motocrossactionmag.com/mxa-race-test-2017-ktm-350sxf/","2016")
R('identity','2017 changes',C,[2017],"2017 350 SX-F changes: WP AER 48 air fork (3.6 lb lighter than the 4CS), a stiffer top clamp, a 42 N/mm shock spring (was 48), a handlebar multi-switch with two maps, launch control and traction control, a longer rear brake pedal with milder pads, aluminium head stays and an hour meter. 221 lb; list price $9,199.",{'fork':'WP AER 48 (air)','shock_spring':'42 N/mm','weight_lb':221,'msrp_usd':9199},'OEM',s2)
R('setups','2017-2018 tester settings (AER)',C,[2017,2018],"A magazine test crew's 2017-2018 350 SX-F setup: fork air 140 psi (stock 154; testers ranged from 130 to 145), compression 20 clicks out (stock 12), rebound 15 out (stock 12), legs at the third line. Shock: the stock 42 N/mm spring suits lighter riders, around 180 lb use 45 and over 200 lb use 48; 105 mm sag (stock 110), high-speed compression 1-3/4 turns out (stock 2), low-speed 15 clicks out, rebound 10 out (stock 15).",{'fork_psi':'140 (stock 154)','fork':'comp 20 out (stock 12), reb 15 out (stock 12), third line','shock':'42-48 N/mm by weight, sag 105 mm, HSC 1-3/4 turns, LSC 15 out, reb 10 out'},'TUNER',s2)
R('ecu_electronics','2016-2018 maps and launch control',C,G,"On the 2016 350 SX-F a handlebar switch changes maps and a dial in the airbox chooses which maps the switch can reach; from 2017 the left-bar multi-switch does it all: map 1 standard, map 2 aggressive (every tester's choice; there is no mellow map), traction control on its own button, and launch control by pressing both buttons until the light flashes. Launch control drops out if the revs fall by more than 30% on the line. Traction control helps on hardpack and mud and gets in the way in loam.",{'map_1':'standard','map_2':'aggressive'},'TUNER',s2)
s3=F.src(M,"Motocross Action - 2018 KTM 350SXF race test","https://motocrossactionmag.com/mxa-race-test-2018-ktm-350sxf","2017")
R('identity','2018 changes',C,[2018],"2018 350 SX-F changes: AER fork with a new air seal, a steel mid-valve in place of the ceramic one and revised compression valving (about 5% more low-speed, 10% less high-speed), a revalved shock, nitrided clutch steels, a new gearbox bearing, a stronger battery and an orange frame.",{},'OEM',s3)
R('known_issues','2016-2018 weak points and fixes',C,G,"Tester findings on the 2016-2018 350 SX-F: sprocket bolts and spokes loosen constantly and some spokes broke, the fork air bleeder strips, the gas cap sticks, neutral is hard to find in the pits, the exhaust needs the shock out to remove, the oil plug by the shifter weeps, the 2017 rear pads are grabby and squeal (2016 pads or a chamfer on the leading edge), the 2017 fork fluttered over braking bumps and its air seal could leak when cold (both revised for 2018), and cold starting was weak with the early battery.",{},'TUNER',s3)

s=F.src(M,"Motocross Action - 2019 KTM 350SXF race test","https://motocrossactionmag.com/mxa-race-test-the-real-test-of-the-2019-ktm-350sxf","2018")
R('identity','2019 changes',C,[2019],"2019 350 SX-F changes: a new frame 10% stiffer in torsion, a Pankl gearbox, a diaphragm-spring clutch, a new ECU, exhaust, top clamp and tank, radiators 12 mm lower, a swingarm 5 mm longer, a subframe 40 mm longer, a larger throttle body, a head 200 g lighter, a new airbox and clamps 5 mm wider.",{},'OEM',s)
R('power_feel','2019 dyno and weight',C,[2019],"On a magazine dyno the 2019 350 SX-F peaked at 53.30 hp, about 0.2 below the 2018, with less from 5,000 to 8,000 rpm and more in the upper middle: 50.82 hp at 10,000 rpm against 48.76. It weighed 221 lb. Stronger roll-on from 8,000 rpm and clean to the 13,400 rpm limit.",{'peak_hp':53.3,'hp_at_10000':50.82,'weight_lb':221},'MEASURED',s,'high')
R('setups','2019 tester settings (AER)',C,[2019],"A magazine test crew's 2019 350 SX-F setup: fork air 138 psi (stock 150), compression 25 clicks out (stock 15), rebound 15 out, legs at the third line, oil lowered 10-20 mm if the mid-stroke is harsh. Shock 42 N/mm spring, 105 mm sag (stock 110), high-speed compression 1-3/4 turns out (stock 2), low-speed 15 clicks out, rebound 10 out (stock 15).",{'fork_psi':'138 (stock 150)','fork':'comp 25 out (stock 15), reb 15 out, third line','shock':'42 N/mm, sag 105 mm, HSC 1-3/4 turns, LSC 15 out, reb 10 out'},'TUNER',s)
R('engine_mods','2019 airbox cover',C,[2019],"The 2019 350 SX-F airbox holds back the low-to-mid. Drilling the airbox cover (testers used a 1-1/4 in spade bit) gained 1 to 1.5 hp.",{'gain_hp':'1-1.5'},'MEASURED',s)

if __name__=='__main__': F.write()
